139	private:
140		inline bool EntryShouldBeAdded(const string_t &sort_key) {
141			if (heap.size() < heap_size) {
142				// heap is full - check the latest entry
143				return true;
144			}
145			if (sort_key < heap.front().sort_key) {
146				// sort key is smaller than current max value
147				return true;
148			}
149			// heap is full and there is no room for the entry
150			return false;
151		}
