153		inline void AddEntryToHeap(const TopNEntry &entry) {
154			if (heap.size() >= heap_size) {
155				std::pop_heap(heap.begin(), heap.end());
156				heap.pop_back();
157			}
158			heap.push_back(entry);
159			std::push_heap(heap.begin(), heap.end());
160		}
