166	TopNHeap::TopNHeap(ClientContext &context, Allocator &allocator, const vector<LogicalType> &payload_types_p,
167	                   const vector<BoundOrderByNode> &orders_p, idx_t limit, idx_t offset)
168	    : allocator(allocator), buffer_manager(BufferManager::GetBufferManager(context)), arena_allocator(allocator),
169	      heap(arena_allocator), payload_types(payload_types_p), orders(orders_p), limit(limit), offset(offset),
170	      heap_size(limit + offset), executor(context), sort_key_heap(allocator), matching_sel(STANDARD_VECTOR_SIZE),
171	      final_sel(STANDARD_VECTOR_SIZE), true_sel(STANDARD_VECTOR_SIZE), false_sel(STANDARD_VECTOR_SIZE),
172	      new_remaining_sel(STANDARD_VECTOR_SIZE) {
173		// initialize the executor and the sort_chunk
174		vector<LogicalType> sort_types;
175		for (auto &order : orders) {
176			auto &expr = order.expression;
177			sort_types.push_back(expr->GetReturnType());
178			executor.AddExpression(*expr);
179			modifiers.emplace_back(order.type, order.null_order);
180		}
181		heap.reserve(InitialHeapAllocSize());
182		vector<LogicalType> sort_keys_type {LogicalType::BLOB};
183		sort_keys.Initialize(allocator, sort_keys_type);
184		heap_data.Initialize(allocator, payload_types, InitialHeapAllocSize());
