201	void TopNHeap::AddSmallHeap(DataChunk &input, const Vector &sort_keys_vec) {
202		// insert the sort keys into the priority queue
203		constexpr idx_t BASE_INDEX = NumericLimits<uint32_t>::Maximum();
204	
205		bool any_added = false;
206		auto sort_key_values = FlatVector::GetData<string_t>(sort_keys_vec);
207		for (idx_t r = 0; r < input.size(); r++) {
208			auto &sort_key = sort_key_values[r];
209			if (!EntryShouldBeAdded(sort_key)) {
210				continue;
211			}
212			// replace the previous top entry with the new entry
213			TopNEntry entry;
214			entry.sort_key = sort_key;
215			entry.index = BASE_INDEX + r;
216			AddEntryToHeap(entry);
217			any_added = true;
218		}
219		if (!any_added) {
220			// early-out: no matches
221			return;
222		}
223	
224		// for all matching entries we need to copy over the corresponding payload values
225		idx_t match_count = 0;
226		for (auto &entry : heap) {
227			if (entry.index < BASE_INDEX) {
228				continue;
229			}
230			// this entry was added in this chunk
231			// copy over the string to the string heap
232			entry.sort_key = sort_key_heap.AddBlob(entry.sort_key);
233			// to finalize the addition of this entry we need to move over the payload data
234			matching_sel.set_index(match_count, entry.index - BASE_INDEX);
235			entry.index = heap_data.size() + match_count;
236			match_count++;
237		}
238	
239		// copy over the input rows to the payload chunk
240		heap_data.Append(input, matching_sel, match_count, VectorAppendMode::ALLOW_RESIZE);
241	}
242	
243	void TopNHeap::AddLargeHeap(DataChunk &input, const Vector &sort_keys_vec) {
244		auto sort_key_values = FlatVector::GetData<string_t>(sort_keys_vec);
245		idx_t base_index = heap_data.size();
246		idx_t match_count = 0;
247		for (idx_t r = 0; r < input.size(); r++) {
248			auto &sort_key = sort_key_values[r];
249			if (!EntryShouldBeAdded(sort_key)) {
250				continue;
251			}
252			// replace the previous top entry with the new entry
253			TopNEntry entry;
254			entry.sort_key = sort_key_heap.AddBlob(sort_key);
255			entry.index = base_index + match_count;
256			AddEntryToHeap(entry);
257			matching_sel.set_index(match_count++, r);
258		}
259		if (match_count == 0) {
260			// early-out: no matches
261			return;
262		}
263	
264		// copy over the input rows to the payload chunk
265		heap_data.Append(input, matching_sel, match_count, VectorAppendMode::ALLOW_RESIZE);
266	}
