505	SinkResultType PhysicalTopN::Sink(ExecutionContext &context, DataChunk &chunk, OperatorSinkInput &input) const {
506		// append to the local sink state
507		auto &gstate = input.global_state.Cast<TopNGlobalSinkState>();
508		auto &sink = input.local_state.Cast<TopNLocalSinkState>();
